const scan = $('Scan Repository').item.json;
const agent = $json;
const input = $('Mimir Webhook').item.json.body ?? {};
const request = String(input.request ?? '');
const tokens = [...new Set(
  request.toLowerCase().split(/[^a-z0-9_.-]+/).filter((token) => token.length >= 3)
)].slice(0, 30);

const paths = new Map();
function add(path, base, reason) {
  if (!path) return;
  const lower = String(path).toLowerCase();
  let score = base;
  for (const token of tokens) if (lower.includes(token)) score += 10;
  const current = paths.get(path);
  if (!current || score > current.score) paths.set(path, { path, score, reason });
}

for (const hotspot of scan.hotspots ?? []) add(hotspot.path, Math.min(hotspot.touches ?? 0, 15), 'recently active file');
for (const file of scan.largest_files ?? []) add(file.path, Math.min(Math.ceil((file.lines ?? 0) / 200), 8), 'large implementation surface');
for (const file of scan.key_files ?? []) add(file.path, 6, 'project/configuration entry point');
for (const finding of scan.findings ?? []) add(finding.path, finding.severity === 'high' ? 7 : 3, 'existing risk signal');

const affectedCandidates = [...paths.values()]
  .filter((item) => item.score > 0)
  .sort((a, b) => b.score - a.score)
  .slice(0, 15);

const primary = affectedCandidates.slice(0, 6).map((item) => item.path);
const baselinePlan = [
  {
    phase: 1,
    name: 'Ground the change',
    actions: [
      `Inspect the current behavior around: ${primary.join(', ') || 'the repository entry points'}`,
      'Confirm interfaces, configuration boundaries, and existing tests before editing.'
    ]
  },
  {
    phase: 2,
    name: 'Implement incrementally',
    actions: [
      `Implement the requested change: ${request}`,
      'Keep changes scoped to the smallest coherent module boundary and preserve existing contracts unless required otherwise.'
    ]
  },
  {
    phase: 3,
    name: 'Validate',
    actions: [
      'Run the repository-native test, lint, typecheck, and build commands.',
      'Re-run deterministic Mimir scanning and compare new high/critical findings against this baseline.'
    ]
  },
  {
    phase: 4,
    name: 'Review and document',
    actions: [
      'Review configuration, security, failure paths, and backwards compatibility.',
      'Update docs or examples when public behavior or setup changes.'
    ]
  }
];

return [{
  json: {
    status: 'completed',
    workflow: 'implementation-plan',
    run_id: String($execution.id),
    contract_version: 3,
    repository: scan.repository,
    requested_ref: scan.requested_ref,
    commit: scan.commit,
    request,
    depth: input.depth ?? 'standard',
    affected_candidates: affectedCandidates,
    plan: Array.isArray(agent.analysis?.plan) ? agent.analysis.plan : baselinePlan,
    deterministic_baseline_plan: baselinePlan,
    agent_analysis: {
      configured: Boolean(agent.configured),
      mode: agent.mode ?? 'unknown',
      model: agent.model ?? null,
      latency_ms: agent.latency_ms ?? null,
      summary: agent.analysis?.summary ?? null,
      risks: agent.analysis?.risks ?? [],
      error: agent.error ?? null,
      usage: agent.usage ?? null
    },
    repository_context: {
      languages: scan.languages ?? [],
      hotspots: (scan.hotspots ?? []).slice(0, 12),
      largest_files: (scan.largest_files ?? []).slice(0, 12),
      findings_summary: scan.findings_summary ?? {}
    },
    constraints: input.constraints ?? []
  }
}];
